import type { AgentMessage } from '@earendil-works/pi-agent-core';
import type { TodoHistoryProjection } from './todo-cadence.js';
import type { BackgroundHistoryProjection } from './background-cadence.js';
import { normalizeTodoItems, TODO_CADENCE_INTERVAL } from '../compat.js';

/** Host-produced replay checkpoint. Never generated by the summary model or parsed from prose. */
export interface ContextDomainState {
  readonly version: 1;
  readonly todo: TodoHistoryProjection;
  readonly background: BackgroundHistoryProjection;
}

export function readContextDomainState(
  message: AgentMessage | undefined,
): ContextDomainState | undefined {
  if (!message || message.role !== 'compactionSummary') return undefined;
  const value = Reflect.get(message, 'contextState');
  if (!record(value) || value.version !== 1 || !record(value.todo) || !record(value.background))
    return undefined;
  const todo = value.todo;
  const background = value.background;
  if (
    typeof todo.reminderSinceTodoWrite !== 'boolean' ||
    typeof background.hasBackgroundState !== 'boolean' ||
    !count(background.assistantIterationsSinceReminder)
  )
    return undefined;
  const items = todo.todoState === undefined ? undefined : normalizeTodoItems(todo.todoState);
  if (todo.todoState !== undefined && items === undefined) return undefined;
  const cadence = todo.todoCadence;
  if (
    cadence !== undefined &&
    (!record(cadence) ||
      !count(cadence.assistantIterationsSinceTodoWrite) ||
      !count(cadence.assistantIterationsSinceReminder))
  )
    return undefined;
  if (
    background.observedTerminalCount !== undefined &&
    (!Number.isSafeInteger(background.observedTerminalCount) ||
      Number(background.observedTerminalCount) < 0)
  )
    return undefined;
  if (
    background.observedTaskKeys !== undefined &&
    (!Array.isArray(background.observedTaskKeys) ||
      background.observedTaskKeys.length > 256 ||
      !background.observedTaskKeys.every((key: unknown) => typeof key === 'string'))
  )
    return undefined;
  return {
    version: 1,
    todo: {
      reminderSinceTodoWrite: todo.reminderSinceTodoWrite,
      ...(items === undefined ? {} : { todoState: items }),
      ...(cadence === undefined
        ? {}
        : {
            todoCadence: {
              assistantIterationsSinceTodoWrite: Number(cadence.assistantIterationsSinceTodoWrite),
              assistantIterationsSinceReminder: Number(cadence.assistantIterationsSinceReminder),
            },
          }),
    },
    background: {
      hasBackgroundState: background.hasBackgroundState,
      assistantIterationsSinceReminder: background.assistantIterationsSinceReminder,
      ...(background.observedTerminalCount === undefined
        ? {}
        : { observedTerminalCount: Number(background.observedTerminalCount) }),
      ...(background.observedTaskKeys === undefined
        ? {}
        : { observedTaskKeys: [...background.observedTaskKeys] }),
    },
  };
}
function record(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}
function count(value: unknown): value is number {
  return (
    Number.isSafeInteger(value) && Number(value) >= 0 && Number(value) <= TODO_CADENCE_INTERVAL
  );
}
